import os, re

# Search for for-if-add patterns in dex directories (not yet covered)
found = []
skip_dirs = {'jadx/core/utils', 'jadx/core/dex/nodes/RootNode', 'jadx/core/dex/visitors/blocks', 'jadx/core/dex/visitors/kotlin'}
