    for f in files:
        if not f.endswith('.java'):
            continue
        path = os.path.join(root, f)
        content = open(path).read()
        lines = content.split('\n')
        for i, line in enumerate(lines):
            if 'new ArrayList<>()' in line or 'new ArrayList<>(list' in line.lower():
                # Look ahead for a simple for + if + add
                context = '\n'.join(lines[i:i+8])
                if re.search(r'for\s*\(.*\)\s*\{', context) and re.search(r'if\s*\(', context) and '.add(' in context:
