package jadx.core.dex.visitors.typeinference;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

import org.jetbrains.annotations.Nullable;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import jadx.core.Consts;
import jadx.core.dex.instructions.InsnType;
import jadx.core.dex.instructions.args.ArgType;
import jadx.core.dex.instructions.args.InsnArg;
import jadx.core.dex.instructions.args.PrimitiveType;
import jadx.core.dex.instructions.args.RegisterArg;
import jadx.core.dex.instructions.args.SSAVar;
import jadx.core.dex.nodes.InsnNode;
import jadx.core.dex.nodes.MethodNode;

/**
 * Slow and memory consuming multi-variable type search algorithm.
 * Used only if fast type propagation is failed for some variables.
 * <p>
 * Stages description:
 * - find all possible candidate types within bounds
 * - build dynamic constraint list for every variable
 * - run search by checking all candidates
 */
public class TypeSearch {
	private static final Logger LOG = LoggerFactory.getLogger(TypeSearch.class);

	private static final int VARS_PROCESS_LIMIT = 5_000;
	private static final int CANDIDATES_COUNT_LIMIT = 10;
	private static final int SEARCH_ITERATION_LIMIT = 1_000_000;

	private final MethodNode mth;
	private final TypeSearchState state;
	private final TypeCompare typeCompare;
	private final TypeUpdate typeUpdate;

	public TypeSearch(MethodNode mth) {
		this.mth = mth;
		this.state = new TypeSearchState(mth);
		this.typeUpdate = mth.root().getTypeUpdate();
		this.typeCompare = typeUpdate.getTypeCompare();
	}

	public boolean run() {
		if (mth.getSVars().size() > VARS_PROCESS_LIMIT) {
			mth.addWarnComment("Multi-variable search skipped. Vars limit reached: " + mth.getSVars().size()
					+ " (expected less than " + VARS_PROCESS_LIMIT + ")");
			return false;
		}
		mth.getSVars().forEach(this::fillTypeCandidates);
		mth.getSVars().forEach(this::collectConstraints);

		// quick search for variables without dependencies
		state.getUnresolvedVars().forEach(this::resolveIndependentVariables);

		boolean searchSuccess;
		List<TypeSearchVarInfo> vars = state.getUnresolvedVars();
		if (vars.isEmpty()) {
			searchSuccess = true;
		} else {
			searchSuccess = search(vars) && fullCheck(vars);
			if (Consts.DEBUG_TYPE_INFERENCE && !searchSuccess) {
				LOG.debug("Multi-variable search failed");
			}
		}
		if (searchSuccess) {
			return applyResolvedVars();
		}
		return false;
	}

	private boolean applyResolvedVars() {
		List<TypeSearchVarInfo> resolvedVars = state.getResolvedVars();
		List<TypeSearchVarInfo> updatedVars = new ArrayList<>();
		for (TypeSearchVarInfo var : resolvedVars) {
			SSAVar ssaVar = var.getVar();
			ArgType resolvedType = var.getCurrentType();
			if (!resolvedType.isTypeKnown()) {
				// ignore unknown variables
				continue;
			}
			if (resolvedType.equals(ssaVar.getTypeInfo().getType())) {
				// type already set
				continue;
			}
			ssaVar.setType(resolvedType);
			updatedVars.add(var);
		}
		boolean applySuccess = true;
		for (TypeSearchVarInfo var : updatedVars) {
			TypeUpdateResult res = typeUpdate.applyWithWiderIgnSame(mth, var.getVar(), var.getCurrentType());
			if (res == TypeUpdateResult.REJECT) {
				mth.addDebugComment("Multi-variable search result rejected for " + var);
				applySuccess = false;
			}
		}
		return applySuccess;
	}

	private boolean search(List<TypeSearchVarInfo> vars) {
		int len = vars.size();
		if (Consts.DEBUG_TYPE_INFERENCE) {
			LOG.debug("Run multi-variable search for {} vars: ", len);
			StringBuilder sb = new StringBuilder();
			long count = 1;
			for (TypeSearchVarInfo var : vars) {
				LOG.debug("  {}", var);
				int size = var.getCandidateTypes().size();
				sb.append(" * ").append(size);
				count *= size;
			}
			sb.append(" = ").append(count);
			LOG.debug(" max iterations count = {}", sb);
		}

		// prepare vars
		for (TypeSearchVarInfo var : vars) {
			var.reset();
		}
		// check all types combinations
		int n = 0;
		int i = 0;
		while (!fullCheck(vars)) {
			TypeSearchVarInfo first = vars.get(i);
			if (first.nextType()) {
				int k = i + 1;
				if (k >= len) {
					return false;
				}
				TypeSearchVarInfo next = vars.get(k);
				while (true) {
					if (next.nextType()) {
						k++;
						if (k >= len) {
							return false;
						}
						next = vars.get(k);
					} else {
						break;
					}
				}
			}
			n++;
			if (n > SEARCH_ITERATION_LIMIT) {
				if (Consts.DEBUG_TYPE_INFERENCE) {
					LOG.debug(" > iterations limit reached: {}", SEARCH_ITERATION_LIMIT);
				}
				return false;
			}
		}
		if (Consts.DEBUG_TYPE_INFERENCE) {
			LOG.debug(" > done after {} iterations", n);
		}
		// mark all vars as resolved
		for (TypeSearchVarInfo var : vars) {
			var.setTypeResolved(true);
		}
		return true;
	}

	private boolean resolveIndependentVariables(TypeSearchVarInfo varInfo) {
		boolean allRelatedVarsResolved = varInfo.getConstraints().stream()
				.flatMap(c -> c.getRelatedVars().stream())
				.allMatch(v -> state.getVarInfo(v).isTypeResolved());
		if (!allRelatedVarsResolved) {
			return false;
		}
		// variable is independent, run single search
		varInfo.reset();
		do {
			if (singleCheck(varInfo)) {
				varInfo.setTypeResolved(true);
				return true;
			}
		} while (!varInfo.nextType());

		return false;
	}

	private boolean fullCheck(List<TypeSearchVarInfo> vars) {
		for (TypeSearchVarInfo var : vars) {
			if (!singleCheck(var)) {
				return false;
			}
		}
		return true;
	}

	private boolean singleCheck(TypeSearchVarInfo var) {
		if (var.isTypeResolved()) {
			return true;
		}
		for (ITypeConstraint constraint : var.getConstraints()) {
			if (!constraint.check(state)) {
				return false;
			}
		}
		return true;
	}

	private void fillTypeCandidates(SSAVar ssaVar) {
		TypeSearchVarInfo varInfo = state.getVarInfo(ssaVar);
		ArgType immutableType = ssaVar.getImmutableType();
		if (immutableType != null) {
			varInfo.markResolved(immutableType);
			return;
		}
		ArgType currentType = ssaVar.getTypeInfo().getType();
		if (currentType.isTypeKnown()) {
			varInfo.markResolved(currentType);
			return;
		}

		Set<ArgType> assigns = new LinkedHashSet<>();
		Set<ArgType> uses = new LinkedHashSet<>();
		Set<ITypeBound> bounds = ssaVar.getTypeInfo().getBounds();
		for (ITypeBound bound : bounds) {
			if (bound.getBound() == BoundEnum.ASSIGN) {
				assigns.add(bound.getType());
			} else {
				uses.add(bound.getType());
			}
		}

		Set<ArgType> candidateTypes = new LinkedHashSet<>();
		addCandidateTypes(bounds, candidateTypes, assigns);
		addCandidateTypes(bounds, candidateTypes, uses);

		for (ArgType assignType : assigns) {
			addCandidateTypes(bounds, candidateTypes, getWiderTypes(assignType));
		}
		for (ArgType useType : uses) {
			addCandidateTypes(bounds, candidateTypes, getNarrowTypes(useType));
		}

		addUsageTypeCandidates(ssaVar, bounds, candidateTypes);

		int size = candidateTypes.size();
		if (size == 0) {
			varInfo.setTypeResolved(true);
			varInfo.setCurrentType(ArgType.UNKNOWN);
			varInfo.setCandidateTypes(List.of());
		} else if (size == 1) {
			varInfo.setTypeResolved(true);
			varInfo.setCurrentType(candidateTypes.iterator().next());
			varInfo.setCandidateTypes(List.of());
		} else {
			varInfo.setTypeResolved(false);
			varInfo.setCurrentType(ArgType.UNKNOWN);
			List<ArgType> types = new ArrayList<>(candidateTypes);
			types.sort(typeCompare.getReversedComparator());
			varInfo.setCandidateTypes(Collections.unmodifiableList(types));
		}
	}

	private void addUsageTypeCandidates(SSAVar ssaVar, Set<ITypeBound> bounds, Set<ArgType> candidateTypes) {
		for (RegisterArg useArg : ssaVar.getUseList()) {
			InsnNode parentInsn = useArg.getParentInsn();
			if (parentInsn != null) {
				InsnType insnType = parentInsn.getType();
				if (insnType == InsnType.APUT) {
					ArgType aputType = parentInsn.getArg(2).getType();
					if (aputType.isTypeKnown()) {
						addCandidateType(bounds, candidateTypes, ArgType.array(aputType));
					}
				}
			}
		}
	}

	private void addCandidateTypes(Set<ITypeBound> bounds, Set<ArgType> collectedTypes, Collection<ArgType> candidateTypes) {
		for (ArgType candidateType : candidateTypes) {
			if (addCandidateType(bounds, collectedTypes, candidateType)) {
				return;
			}
		}
	}

	private boolean addCandidateType(Set<ITypeBound> bounds, Set<ArgType> collectedTypes, ArgType candidateType) {
		if (candidateType.isTypeKnown() && typeUpdate.inBounds(bounds, candidateType)) {
			collectedTypes.add(candidateType);
			if (collectedTypes.size() > CANDIDATES_COUNT_LIMIT) {
				return true;
			}
		}
		return false;
	}

	private List<ArgType> getWiderTypes(ArgType type) {
		if (type.isTypeKnown()) {
			if (type.isObject()) {
				Set<String> ancestors = mth.root().getClsp().getSuperTypes(type.getObject());
				return ancestors.stream().map(ArgType::object).collect(Collectors.toList());
			}
		} else {
			return expandUnknownType(type);
		}
		return List.of();
	}

	private List<ArgType> getNarrowTypes(ArgType type) {
		if (type.isTypeKnown()) {
			if (type.isObject()) {
				if (type.equals(ArgType.OBJECT)) {
					// a lot of objects to return
					return List.of(ArgType.OBJECT);
				}
				List<String> impList = mth.root().getClsp().getImplementations(type.getObject());
				return impList.stream().map(ArgType::object).collect(Collectors.toList());
			}
		} else {
			return expandUnknownType(type);
		}
		return List.of();
	}

	private List<ArgType> expandUnknownType(ArgType type) {
		List<ArgType> list = new ArrayList<>();
		for (PrimitiveType possibleType : type.getPossibleTypes()) {
			list.add(ArgType.convertFromPrimitiveType(possibleType));
		}
		return list;
	}

	private void collectConstraints(SSAVar var) {
		TypeSearchVarInfo varInfo = state.getVarInfo(var);
		if (varInfo.isTypeResolved()) {
			varInfo.setConstraints(List.of());
			return;
		}
		varInfo.setConstraints(new ArrayList<>());
		addConstraint(varInfo, makeConstraint(var.getAssign()));
		for (RegisterArg regArg : var.getUseList()) {
			addConstraint(varInfo, makeConstraint(regArg));
		}
	}

	private void addConstraint(TypeSearchVarInfo varInfo, ITypeConstraint constraint) {
		if (constraint != null) {
			varInfo.getConstraints().add(constraint);
		}
	}

	@Nullable
	private ITypeConstraint makeConstraint(RegisterArg arg) {
		InsnNode insn = arg.getParentInsn();
		if (insn == null || arg.isTypeImmutable()) {
			return null;
		}
		switch (insn.getType()) {
			case MOVE:
				return makeMoveConstraint(insn, arg);

			case PHI:
				return makePhiConstraint(insn, arg);

			default:
				return null;
		}
	}

	@Nullable
	private ITypeConstraint makeMoveConstraint(InsnNode insn, RegisterArg arg) {
		if (!insn.getArg(0).isRegister()) {
			return null;
		}
		return new AbstractTypeConstraint(insn, arg) {
			@Override
			public boolean check(TypeSearchState state) {
				ArgType resType = state.getArgType(insn.getResult());
				ArgType argType = state.getArgType(insn.getArg(0));
				TypeCompareEnum res = typeCompare.compareTypes(resType, argType);
				return res.isEqual() || res.isWider();
			}
		};
	}

	private ITypeConstraint makePhiConstraint(InsnNode insn, RegisterArg arg) {
		return new AbstractTypeConstraint(insn, arg) {
			@Override
			public boolean check(TypeSearchState state) {
				ArgType resType = state.getArgType(insn.getResult());
				for (InsnArg insnArg : insn.getArguments()) {
					ArgType argType = state.getArgType(insnArg);
					if (!argType.equals(resType)) {
						return false;
					}
				}
				return true;
			}
		};
	}
}

package jadx.api.plugins.options.impl;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.stream.Collectors;

import org.jetbrains.annotations.Nullable;

import jadx.api.plugins.options.JadxPluginOptions;
import jadx.api.plugins.options.OptionDescription;
import jadx.api.plugins.options.OptionFlag;
import jadx.api.plugins.options.OptionType;

/**
 * Base class for {@link JadxPluginOptions} implementation
 * <p>
 * Override {@link BasePluginOptionsBuilder#registerOptions()} method
 * and use *option methods to add option info.
 */
@SuppressWarnings("unused")
public abstract class BasePluginOptionsBuilder implements JadxPluginOptions {

	private final List<OptionData<?>> options = new ArrayList<>();

	public abstract void registerOptions();

	public BasePluginOptionsBuilder() {
		registerOptions();
		for (OptionData<?> option : options) {
			option.validate();
		}
	}

	public <T> OptionBuilder<T> option(String name) {
		return addOption(new OptionData<>(name));
	}

	public <T> OptionBuilder<T> option(String name, Class<T> optionType) {
		return addOption(new OptionData<>(name));
	}

	public OptionBuilder<Boolean> boolOption(String name) {
		return addOption(
				new OptionData<Boolean>(name)
						.type(OptionType.BOOLEAN)
						.values(Arrays.asList(Boolean.TRUE, Boolean.FALSE))
						.formatter(b -> b ? "yes" : "no")
						.parser(val -> parseBoolOption(name, val)));
	}

	public OptionBuilder<String> strOption(String name) {
		return addOption(
				new OptionData<String>(name)
						.type(OptionType.STRING)
						.formatter(v -> v)
						.parser(v -> v));
	}

	public OptionBuilder<Integer> intOption(String name) {
		return addOption(
				new OptionData<Integer>(name)
						.type(OptionType.NUMBER)
						.formatter(Object::toString)
						.parser(Integer::parseInt));
	}

	public <E extends Enum<?>> OptionBuilder<E> enumOption(String name, E[] values, Function<String, E> valueOf) {
		return addOption(
				new OptionData<E>(name)
						.type(OptionType.STRING)
						.values(Arrays.asList(values))
						.formatter(v -> v.name().toLowerCase(Locale.ROOT))
						.parser(v -> valueOf.apply(v.toUpperCase(Locale.ROOT))));
	}

	@Override
	public void setOptions(Map<String, String> map) {
		for (OptionData<?> option : options) {
			parseOption(option, map.get(option.name));
		}
	}

	@Override
	public List<OptionDescription> getOptionsDescriptions() {
		return Collections.unmodifiableList(options);
	}

	private static <T> void parseOption(OptionData<T> option, @Nullable String value) {
		T parsedValue;
		if (value == null) {
			parsedValue = option.defaultValue;
		} else {
			try {
				parsedValue = option.getParser().apply(value);
			} catch (Exception e) {
				throw new RuntimeException("Parse failed for option: " + option.name + ", value: " + value, e);
			}
		}
		try {
			option.getSetter().accept(parsedValue);
		} catch (Exception e) {
			throw new RuntimeException("Setter invoke failed for option: " + option.name + ", value: " + parsedValue, e);
		}
	}

	private static boolean parseBoolOption(String name, String val) {
		String valLower = val.trim().toLowerCase(Locale.ROOT);
		if (valLower.equals("yes") || valLower.equals("true")) {
			return true;
		}
		if (valLower.equals("no") || valLower.equals("false")) {
			return false;
		}
		throw new IllegalArgumentException("Unknown value '" + val + "' for option '" + name + "', expect: 'yes' or 'no'");
	}

	private <T> OptionBuilder<T> addOption(OptionBuilder<T> optionData) {
		this.options.add((OptionData<?>) optionData);
		return optionData;
	}

	protected static class OptionData<T> implements OptionDescription, OptionBuilder<T> {
		private final String name;
		private String desc;
		private List<T> values = List.of();
		private OptionType type = OptionType.STRING;
		private Set<OptionFlag> flags = EnumSet.noneOf(OptionFlag.class);
		private Function<String, T> parser;
		private Function<T, String> formatter;
		private Consumer<T> setter;
		private T defaultValue;

		public OptionData(String name) {
			this.name = name;
		}

		@Override
		public String name() {
			return name;
		}

		@Override
		public String description() {
			return desc;
		}

		@Override
		public List<String> values() {
			return values.stream().map(formatter).collect(Collectors.toList());
		}

		@Override
		public @Nullable String defaultValue() {
			return formatter.apply(defaultValue);
		}

		@Override
		public OptionType getType() {
			return type;
		}

		@Override
		public Set<OptionFlag> getFlags() {
			return flags;
		}

		@Override
		public OptionBuilder<T> description(String desc) {
			this.desc = desc;
			return this;
		}

		@Override
		public OptionBuilder<T> defaultValue(@Nullable T defValue) {
			this.defaultValue = defValue;
			return this;
		}

		@Override
		public OptionBuilder<T> parser(Function<String, T> parser) {
			this.parser = parser;
			return this;
		}

		@Override
		public OptionBuilder<T> formatter(Function<T, String> formatter) {
			this.formatter = formatter;
			return this;
		}

		@Override
		public OptionBuilder<T> setter(Consumer<T> setter) {
			this.setter = setter;
			return this;
		}

		@Override
		public OptionBuilder<T> type(OptionType optionType) {
			this.type = optionType;
			return this;
		}

		@Override
		public OptionBuilder<T> flags(OptionFlag... flags) {
			this.flags = EnumSet.copyOf(Arrays.asList(flags));
			return this;
		}

		@Override
		public OptionBuilder<T> values(List<T> values) {
			this.values = values;
			return this;
		}

		public Function<String, T> getParser() {
			return parser;
		}

		public Function<T, String> getFormatter() {
			return formatter;
		}

		public Consumer<T> getSetter() {
			return setter;
		}

		public void validate() {
			if (desc == null || desc.isEmpty()) {
				throw new IllegalArgumentException("Description should be set for option: " + name);
			}
			if (parser == null) {
				throw new IllegalArgumentException("Parser should be set for option: " + name);
			}
			if (formatter == null) {
				throw new IllegalArgumentException("Formatter should be set for option: " + name);
			}
			if (setter == null) {
				throw new IllegalArgumentException("Setter should be set for option: " + name);
			}
		}
	}
}

package jadx.gui.ui.graphs;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FlowLayout;
import java.util.Formatter;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import javax.swing.JCheckBox;
import javax.swing.JMenuBar;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.UIManager;

import jadx.api.JavaMethod;
import jadx.api.JavaNode;
import jadx.core.dex.nodes.ClassNode;
import jadx.core.dex.nodes.MethodNode;
import jadx.core.utils.DotGraphUtils;
import jadx.gui.treemodel.JClass;
import jadx.gui.ui.MainWindow;
import jadx.gui.utils.NLS;
import jadx.gui.utils.layout.WrapLayout;

import static jadx.core.utils.DotGraphUtils.formatColor;
import static jadx.core.utils.DotGraphUtils.toDotNodeName;

public class ClassMethodGraphDialog extends GraphDialog {
	private static final long serialVersionUID = -850803763322590708L;

	private static final String FONT = "fontname=\"Courier\" fontsize=12";
	private static final int CALLER_DEPTH_LIMIT = 10;

	private final ClassNode cls;
	private int nextNodeID = 0;
	private Map<JavaMethod, Integer> methodToNodeID;
	private Set<Edge> edges;
	private List<JavaMethod> javaMethods = List.of();
	private boolean longNames = false;

	public ClassMethodGraphDialog(MainWindow mainWindow, ClassNode cls) {
		super(mainWindow, String.format("%s: %s", NLS.str("graph_viewer.method_graph.title"), DotGraphUtils.classFormatName(cls, false)));
		this.cls = cls;
	}

	@Override
	public JMenuBar addMenuBar() {
		JMenuBar menuBar = super.addMenuBar();

		// Long names checkbox
		JCheckBox showLongNames = new JCheckBox(NLS.str("graph_viewer.long_names"));
		showLongNames.setSelected(false);
		showLongNames.addItemListener(e -> {
			longNames = showLongNames.isSelected();
			reload();
		});

		// Assemble menubar panel
		JPanel menuBarPanel = new JPanel();
		menuBarPanel.setOpaque(false);
		menuBarPanel.setLayout(new WrapLayout(FlowLayout.LEFT));
		menuBarPanel.add(showLongNames, BorderLayout.PAGE_START);

		// Add menubar panel to menuBar
		menuBar.add(menuBarPanel);
		return menuBar;
	}

	public static void open(MainWindow window, JClass node) {
		ClassNode cls = node.getCls().getClassNode();
		ClassMethodGraphDialog graphDialog = new ClassMethodGraphDialog(window, cls);
		graphDialog.addMenuBar();
		graphDialog.setVisible(true);
		graphDialog.reload();
	}

	public void reload() {
		SwingUtilities.invokeLater(() -> getPanel().setGraph(generateGraph(cls)));
	}

	private String generateGraph(ClassNode classNode) {
		Color themeBackground = UIManager.getColor("Panel.background");
		Color themeForeground = UIManager.getColor("Label.foreground");
		Color themeShade = UIManager.getColor("TextArea.background");

		String bgColor = "bgcolor=" + formatColor(themeBackground);
		String lineColor = "color=" + formatColor(themeForeground);
		String fontColor = "fontcolor=" + formatColor(themeForeground);
		String shadeColor = "fillcolor=" + formatColor(themeShade);

		try (Formatter f = new Formatter(new StringBuilder())) {
			// graph header
			f.format("digraph G {\n");
			f.format("%s\n", bgColor);
			f.format("node[shape=\"record\" style=\"filled\" %s %s %s %s]\n", FONT, fontColor, lineColor, shadeColor);
			f.format("edge[arrowtail=\"onormal\" arrowhead=\"onormal\" %s %s %s]\n", FONT, fontColor, lineColor);

			nextNodeID = 0;
			methodToNodeID = new HashMap<>();
			edges = new HashSet<>();

			List<MethodNode> methods = classNode.getMethods();
			javaMethods = methods.stream().map(MethodNode::getJavaNode).collect(Collectors.toList());
			for (JavaMethod javaMethod : javaMethods) {
				addNode(f, javaMethod);
				// add caller relationships
				addCallers(0, f, javaMethod);
			}
			// close graph
			f.format("}");
			return f.toString();
		}
	}

	private void addCallers(int depth, Formatter f, JavaMethod javaMethod) {
		if (depth >= CALLER_DEPTH_LIMIT) {
			return;
		}
		List<JavaNode> uses = javaMethod.getUseIn();
		// add "calls" relationships
		for (JavaNode node : uses) {
			if (!(node instanceof JavaMethod)) {
				continue;
			}
			JavaMethod caller = (JavaMethod) node;
			// Do not process callers that are not methods from the class
			if (!javaMethods.contains(node)) {
				continue;
			}
			int nodeID = addNode(f, caller);
			addEdge(f, nodeID, methodToNodeID.get(javaMethod));
			addCallers(depth + 1, f, caller);
		}
	}

	// Add a node representing method to the graph in f. Returns the ID of the new node
	private int addNode(Formatter f, JavaMethod method) {
		int nodeID;
		if (methodToNodeID.containsKey(method)) {
			nodeID = methodToNodeID.get(method);
		} else {
			nodeID = nextNodeID;
			nextNodeID++;
			methodToNodeID.put(method, nodeID);
		}
		String name = DotGraphUtils.methodFormatName(method, longNames);
		f.format("Node_%d [ label=\"{%s}\"]\n", nodeID, toDotNodeName(name));
		if (method.callsSelf()) {
			addEdge(f, nodeID, nodeID);
		}
		return nodeID;
	}

	// Add an edge between sourceID and destID to the graph in f
	private void addEdge(Formatter f, int sourceID, int destID) {
		Edge edge = new Edge(sourceID, destID);
		if (!edges.contains(edge)) {
			f.format("Node_%d -> Node_%d\n", sourceID, destID);
			edges.add(edge);
		}
	}
}

package jadx.gui.ui.codearea.sync.fallback;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;

import jadx.core.utils.Utils;

class MethodDeclaration implements IDeclaration {
	private final AbstractCodeAreaLine line;
	private final Type returnType;
	private final List<Type> argTypes;
	private final String name;

	boolean isStatic;

	public static MethodDeclaration create(JavaCodeAreaLine line) throws FallbackSyncException {
		String methodName = line.extractDeclaredMethodName();
		if (methodName == null) {
			throw new FallbackSyncException("no method name found in java declaration");
		}

		// Get the return string
		String trimmed = line.getTrimmedStr();
		int methodNameStartPos = trimmed.indexOf(methodName);
		// -2 to jump to last char of return type
		// +1 to get to first char of return type
		int returnTypeStartPos = trimmed.lastIndexOf(' ', methodNameStartPos - 2) + 1;
		returnTypeStartPos = returnTypeStartPos > -1 ? returnTypeStartPos : 0;
		String returnStr = trimmed.substring(returnTypeStartPos, methodNameStartPos - 1);

		// Get the arg types
		String argString = trimmed.substring(trimmed.indexOf('(') + 1, trimmed.indexOf(')'));
		String[] argStringParts = argString.split(", ");
		List<String> argTypeStrings = new ArrayList<>();
		for (int i = 0; i < argStringParts.length; i++) {
			String part = argStringParts[i];
			if (part.isEmpty()) {
				break;
			}
			argTypeStrings.add(part.substring(0, part.indexOf(" ")));
		}

		boolean isStatic = trimmed.contains("static ");

		List<Type> argTypes = argTypeStrings.stream().map(s -> Type.fromJavaName(s)).collect(Collectors.toList());
		return new MethodDeclaration(line, Type.fromJavaName(returnStr), argTypes, isStatic, methodName);
	}

	public static MethodDeclaration create(SmaliAreaLine line) throws FallbackSyncException {
		String methodName = line.extractDeclaredMethodName();
		if (methodName == null) {
			throw new FallbackSyncException("no method name found in smali declaration");
		}

		// Get the return string
		String trimmed = line.getTrimmedStr();
		String returnStr = trimmed.substring(trimmed.indexOf(')') + 1);
		returnStr = returnStr.endsWith(";") ? returnStr.substring(0, returnStr.length() - 1) : returnStr;

		boolean isStatic = trimmed.contains("static ");

		return new MethodDeclaration(line, Type.fromSmaliName(returnStr), parseSmaliArgs(trimmed), isStatic, methodName);
	}

	private MethodDeclaration(AbstractCodeAreaLine line, Type returnType, List<Type> argTypes, boolean isStatic, String name) {
		this.line = line;
		this.returnType = returnType;
		this.argTypes = argTypes;
		this.isStatic = isStatic;
		this.name = name;
	}

	@Override
	public String getIdentifyingName() {
		return name;
	}

	@Override
	public AbstractCodeAreaLine getLine() {
		return line;
	}

	private static List<Type> parseSmaliArgs(String lineStr) {
		List<String> argTypeStrings = new ArrayList<>();
		String argString = lineStr.substring(lineStr.indexOf('(') + 1, lineStr.indexOf(')'));
		for (int i = 0; i < argString.length();) {
			char c = argString.charAt(i);
			if (c == 'L') {
				int j = i;
				for (; j < argString.length(); ++j) {
					if (argString.charAt(j) == ';') {
						argTypeStrings.add(argString.substring(i, j + 1));
						break;
					}
				}
				i = j + 1;
			} else if (c == '[') {
				argTypeStrings.add(argString.substring(i, i + 2));
				i += 2;
			} else if (c != ' ') {
				argTypeStrings.add(argString.substring(i, i + 1));
				++i;
			} else {
				++i;
			}
		}
		return argTypeStrings.stream().map(s -> Type.fromSmaliName(s)).collect(Collectors.toList());
	}

	@Override
	public boolean equals(Object o) {
		if (o instanceof MethodDeclaration) {
			MethodDeclaration decl = (MethodDeclaration) o;
			if (!decl.name.equals(this.name)) {
				return false;
			}
			if (decl.isStatic != this.isStatic) {
				return false;
			}
			if (!decl.returnType.equals(this.returnType)) {
				return false;
			}
			if (decl.argTypes.size() != this.argTypes.size()) {
				return false;
			}
			for (int i = 0; i < decl.argTypes.size(); ++i) {
				if (!decl.argTypes.get(i).equals(this.argTypes.get(i))) {
					return false;
				}
			}
			return true;
		}
		return false;
	}

	// Not necessary but removes checkstyle warning
	@Override
	public int hashCode() {
		return Objects.hash(name, isStatic, returnType, argTypes);
	}

	@Override
	public String toString() {
		StringBuilder sb = new StringBuilder();
		sb.append("NAME=").append(name).append("+++")
				.append("RETURN=").append(returnType).append("+++")
				.append("ARGS=");
		for (final var a : argTypes) {
			sb.append(a).append(",");
		}
		return sb.toString();
	}

	private static class Type {
		private String smaliName;
		private String javaName;

		public static Type fromJavaName(String name) {
			return new Type(Utils.javaNameToSmaliName(name), name);
		}

		public static Type fromSmaliName(String name) {
			return new Type(name, Utils.smaliNameToJavaName(name));
		}

		private Type(String smaliName, String javaName) {
			this.smaliName = smaliName;
			this.javaName = javaName;
		}

		private boolean isNonPrimitive() {
			return smaliName.startsWith("L");
		}

		@Override
		public boolean equals(Object o) {
			if (o instanceof Type) {
				Type t = (Type) o;
				if (t.isNonPrimitive() || this.isNonPrimitive()) {
					// One of them might be missing the package prefix
					return t.javaName.endsWith(this.javaName)
							|| this.javaName.endsWith(t.javaName);
				}
				return t.javaName.equals(this.javaName)
						|| t.smaliName.equals(this.smaliName);
				// Slightly less strict - should think about this more
				// && t.smaliName.equals(this.smaliName);
			}
			return false;
		}

		// Not necessary but removes checkstyle warning
		@Override
		public int hashCode() {
			return Objects.hash(this, javaName, smaliName);
		}

		@Override
		public String toString() {
			return "@" + smaliName + "-OR-" + javaName + "@";
		}
	}
}

package jadx.core.dex.visitors.typeinference;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import org.jetbrains.annotations.Nullable;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import jadx.core.Consts;
import jadx.core.dex.instructions.InsnType;
import jadx.core.dex.instructions.args.ArgType;
import jadx.core.dex.instructions.args.InsnArg;
import jadx.core.dex.instructions.args.PrimitiveType;
import jadx.core.dex.instructions.args.RegisterArg;
import jadx.core.dex.instructions.args.SSAVar;
import jadx.core.dex.nodes.InsnNode;
import jadx.core.dex.nodes.MethodNode;

/**
 * Slow and memory consuming multi-variable type search algorithm.
 * Used only if fast type propagation is failed for some variables.
 * <p>
 * Stages description:
 * - find all possible candidate types within bounds
 * - build dynamic constraint list for every variable
 * - run search by checking all candidates
 */
public class TypeSearch {
	private static final Logger LOG = LoggerFactory.getLogger(TypeSearch.class);

	private static final int VARS_PROCESS_LIMIT = 5_000;
	private static final int CANDIDATES_COUNT_LIMIT = 10;
	private static final int SEARCH_ITERATION_LIMIT = 1_000_000;

	private final MethodNode mth;
	private final TypeSearchState state;
	private final TypeCompare typeCompare;
	private final TypeUpdate typeUpdate;

	public TypeSearch(MethodNode mth) {
		this.mth = mth;
		this.state = new TypeSearchState(mth);
		this.typeUpdate = mth.root().getTypeUpdate();
		this.typeCompare = typeUpdate.getTypeCompare();
	}

	public boolean run() {
		if (mth.getSVars().size() > VARS_PROCESS_LIMIT) {
			mth.addWarnComment("Multi-variable search skipped. Vars limit reached: " + mth.getSVars().size()
					+ " (expected less than " + VARS_PROCESS_LIMIT + ")");
			return false;
		}
		mth.getSVars().forEach(this::fillTypeCandidates);
		mth.getSVars().forEach(this::collectConstraints);

		// quick search for variables without dependencies
		state.getUnresolvedVars().forEach(this::resolveIndependentVariables);

		boolean searchSuccess;
		List<TypeSearchVarInfo> vars = state.getUnresolvedVars();
		if (vars.isEmpty()) {
			searchSuccess = true;
		} else {
			searchSuccess = search(vars) && fullCheck(vars);
			if (Consts.DEBUG_TYPE_INFERENCE && !searchSuccess) {
				LOG.debug("Multi-variable search failed");
			}
		}
		if (searchSuccess) {
			return applyResolvedVars();
		}
		return false;
	}

	private boolean applyResolvedVars() {
		List<TypeSearchVarInfo> resolvedVars = state.getResolvedVars();
		List<TypeSearchVarInfo> updatedVars = new ArrayList<>();
		for (TypeSearchVarInfo var : resolvedVars) {
			SSAVar ssaVar = var.getVar();
			ArgType resolvedType = var.getCurrentType();
			if (!resolvedType.isTypeKnown()) {
				// ignore unknown variables
				continue;
			}
			if (resolvedType.equals(ssaVar.getTypeInfo().getType())) {
				// type already set
				continue;
			}
			ssaVar.setType(resolvedType);
			updatedVars.add(var);
		}
		boolean applySuccess = true;
		for (TypeSearchVarInfo var : updatedVars) {
			TypeUpdateResult res = typeUpdate.applyWithWiderIgnSame(mth, var.getVar(), var.getCurrentType());
			if (res == TypeUpdateResult.REJECT) {
				mth.addDebugComment("Multi-variable search result rejected for " + var);
				applySuccess = false;
			}
		}
		return applySuccess;
	}

	private boolean search(List<TypeSearchVarInfo> vars) {
		int len = vars.size();
		if (Consts.DEBUG_TYPE_INFERENCE) {
			LOG.debug("Run multi-variable search for {} vars: ", len);
			StringBuilder sb = new StringBuilder();
			long count = 1;
			for (TypeSearchVarInfo var : vars) {
				LOG.debug("  {}", var);
				int size = var.getCandidateTypes().size();
				sb.append(" * ").append(size);
				count *= size;
			}
			sb.append(" = ").append(count);
			LOG.debug(" max iterations count = {}", sb);
		}

		// prepare vars
		for (TypeSearchVarInfo var : vars) {
			var.reset();
		}
		// check all types combinations
		int n = 0;
		int i = 0;
		while (!fullCheck(vars)) {
			TypeSearchVarInfo first = vars.get(i);
			if (first.nextType()) {
				int k = i + 1;
				if (k >= len) {
					return false;
				}
				TypeSearchVarInfo next = vars.get(k);
				while (true) {
					if (next.nextType()) {
						k++;
						if (k >= len) {
							return false;
						}
						next = vars.get(k);
					} else {
						break;
					}
				}
			}
			n++;
			if (n > SEARCH_ITERATION_LIMIT) {
				if (Consts.DEBUG_TYPE_INFERENCE) {
					LOG.debug(" > iterations limit reached: {}", SEARCH_ITERATION_LIMIT);
				}
				return false;
			}
		}
		if (Consts.DEBUG_TYPE_INFERENCE) {
			LOG.debug(" > done after {} iterations", n);
		}
		// mark all vars as resolved
		for (TypeSearchVarInfo var : vars) {
			var.setTypeResolved(true);
		}
		return true;
	}

	private boolean resolveIndependentVariables(TypeSearchVarInfo varInfo) {
		boolean allRelatedVarsResolved = varInfo.getConstraints().stream()
				.flatMap(c -> c.getRelatedVars().stream())
				.allMatch(v -> state.getVarInfo(v).isTypeResolved());
		if (!allRelatedVarsResolved) {
			return false;
		}
		// variable is independent, run single search
		varInfo.reset();
		do {
			if (singleCheck(varInfo)) {
				varInfo.setTypeResolved(true);
				return true;
			}
		} while (!varInfo.nextType());

		return false;
	}

	private boolean fullCheck(List<TypeSearchVarInfo> vars) {
		for (TypeSearchVarInfo var : vars) {
			if (!singleCheck(var)) {
				return false;
			}
		}
		return true;
	}

	private boolean singleCheck(TypeSearchVarInfo var) {
		if (var.isTypeResolved()) {
			return true;
		}
		for (ITypeConstraint constraint : var.getConstraints()) {
			if (!constraint.check(state)) {
				return false;
			}
		}
		return true;
	}

	private void fillTypeCandidates(SSAVar ssaVar) {
		TypeSearchVarInfo varInfo = state.getVarInfo(ssaVar);
		ArgType immutableType = ssaVar.getImmutableType();
		if (immutableType != null) {
			varInfo.markResolved(immutableType);
			return;
		}
		ArgType currentType = ssaVar.getTypeInfo().getType();
		if (currentType.isTypeKnown()) {
			varInfo.markResolved(currentType);
			return;
		}

		Set<ArgType> assigns = new LinkedHashSet<>();
		Set<ArgType> uses = new LinkedHashSet<>();
		Set<ITypeBound> bounds = ssaVar.getTypeInfo().getBounds();
		for (ITypeBound bound : bounds) {
			if (bound.getBound() == BoundEnum.ASSIGN) {
				assigns.add(bound.getType());
			} else {
				uses.add(bound.getType());
			}
		}

		Set<ArgType> candidateTypes = new LinkedHashSet<>();
		addCandidateTypes(bounds, candidateTypes, assigns);
		addCandidateTypes(bounds, candidateTypes, uses);

		for (ArgType assignType : assigns) {
			addCandidateTypes(bounds, candidateTypes, getWiderTypes(assignType));
		}
		for (ArgType useType : uses) {
			addCandidateTypes(bounds, candidateTypes, getNarrowTypes(useType));
		}

		addUsageTypeCandidates(ssaVar, bounds, candidateTypes);

		int size = candidateTypes.size();
		if (size == 0) {
			varInfo.setTypeResolved(true);
			varInfo.setCurrentType(ArgType.UNKNOWN);
			varInfo.setCandidateTypes(List.of());
		} else if (size == 1) {
			varInfo.setTypeResolved(true);
			varInfo.setCurrentType(candidateTypes.iterator().next());
			varInfo.setCandidateTypes(List.of());
		} else {
			varInfo.setTypeResolved(false);
			varInfo.setCurrentType(ArgType.UNKNOWN);
			List<ArgType> types = new ArrayList<>(candidateTypes);
			types.sort(typeCompare.getReversedComparator());
			varInfo.setCandidateTypes(Collections.unmodifiableList(types));
		}
	}

	private void addUsageTypeCandidates(SSAVar ssaVar, Set<ITypeBound> bounds, Set<ArgType> candidateTypes) {
		for (RegisterArg useArg : ssaVar.getUseList()) {
			InsnNode parentInsn = useArg.getParentInsn();
			if (parentInsn != null) {
				InsnType insnType = parentInsn.getType();
				if (insnType == InsnType.APUT) {
					ArgType aputType = parentInsn.getArg(2).getType();
					if (aputType.isTypeKnown()) {
						addCandidateType(bounds, candidateTypes, ArgType.array(aputType));
					}
				}
			}
		}
	}

	private void addCandidateTypes(Set<ITypeBound> bounds, Set<ArgType> collectedTypes, Collection<ArgType> candidateTypes) {
		for (ArgType candidateType : candidateTypes) {
			if (addCandidateType(bounds, collectedTypes, candidateType)) {
				return;
			}
		}
	}

	private boolean addCandidateType(Set<ITypeBound> bounds, Set<ArgType> collectedTypes, ArgType candidateType) {
		if (candidateType.isTypeKnown() && typeUpdate.inBounds(bounds, candidateType)) {
			collectedTypes.add(candidateType);
			if (collectedTypes.size() > CANDIDATES_COUNT_LIMIT) {
				return true;
			}
		}
		return false;
	}

	private List<ArgType> getWiderTypes(ArgType type) {
		if (type.isTypeKnown()) {
			if (type.isObject()) {
				Set<String> ancestors = mth.root().getClsp().getSuperTypes(type.getObject());
				return ancestors.stream().map(ArgType::object).collect(Collectors.toList());
			}
		} else {
			return expandUnknownType(type);
		}
		return List.of();
	}

	private List<ArgType> getNarrowTypes(ArgType type) {
		if (type.isTypeKnown()) {
			if (type.isObject()) {
				if (type.equals(ArgType.OBJECT)) {
					// a lot of objects to return
					return List.of(ArgType.OBJECT);
				}
				List<String> impList = mth.root().getClsp().getImplementations(type.getObject());
				return impList.stream().map(ArgType::object).collect(Collectors.toList());
			}
		} else {
			return expandUnknownType(type);
		}
		return List.of();
	}

	private List<ArgType> expandUnknownType(ArgType type) {
		List<ArgType> list = new ArrayList<>();
		for (PrimitiveType possibleType : type.getPossibleTypes()) {
			list.add(ArgType.convertFromPrimitiveType(possibleType));
		}
		return list;
	}

	private void collectConstraints(SSAVar var) {
		TypeSearchVarInfo varInfo = state.getVarInfo(var);
		if (varInfo.isTypeResolved()) {
			varInfo.setConstraints(List.of());
			return;
		}
		varInfo.setConstraints(new ArrayList<>());
		addConstraint(varInfo, makeConstraint(var.getAssign()));
		for (RegisterArg regArg : var.getUseList()) {
			addConstraint(varInfo, makeConstraint(regArg));
		}
	}

	private void addConstraint(TypeSearchVarInfo varInfo, ITypeConstraint constraint) {
		if (constraint != null) {
			varInfo.getConstraints().add(constraint);
		}
	}

	@Nullable
	private ITypeConstraint makeConstraint(RegisterArg arg) {
		InsnNode insn = arg.getParentInsn();
		if (insn == null || arg.isTypeImmutable()) {
			return null;
		}
		switch (insn.getType()) {
			case MOVE:
				return makeMoveConstraint(insn, arg);

			case PHI:
				return makePhiConstraint(insn, arg);

			default:
				return null;
		}
	}

	@Nullable
	private ITypeConstraint makeMoveConstraint(InsnNode insn, RegisterArg arg) {
		if (!insn.getArg(0).isRegister()) {
			return null;
		}
		return new AbstractTypeConstraint(insn, arg) {
			@Override
			public boolean check(TypeSearchState state) {
				ArgType resType = state.getArgType(insn.getResult());
				ArgType argType = state.getArgType(insn.getArg(0));
				TypeCompareEnum res = typeCompare.compareTypes(resType, argType);
				return res.isEqual() || res.isWider();
			}
		};
	}

	private ITypeConstraint makePhiConstraint(InsnNode insn, RegisterArg arg) {
		return new AbstractTypeConstraint(insn, arg) {
			@Override
			public boolean check(TypeSearchState state) {
				ArgType resType = state.getArgType(insn.getResult());
				for (InsnArg insnArg : insn.getArguments()) {
					ArgType argType = state.getArgType(insnArg);
					if (!argType.equals(resType)) {
						return false;
					}
				}
				return true;
			}
		};
	}
}

package jadx.api.plugins.options.impl;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Function;
import org.jetbrains.annotations.Nullable;

import jadx.api.plugins.options.JadxPluginOptions;
import jadx.api.plugins.options.OptionDescription;
import jadx.api.plugins.options.OptionFlag;
import jadx.api.plugins.options.OptionType;

/**
 * Base class for {@link JadxPluginOptions} implementation
 * <p>
 * Override {@link BasePluginOptionsBuilder#registerOptions()} method
 * and use *option methods to add option info.
 */
@SuppressWarnings("unused")
public abstract class BasePluginOptionsBuilder implements JadxPluginOptions {

	private final List<OptionData<?>> options = new ArrayList<>();

	public abstract void registerOptions();

	public BasePluginOptionsBuilder() {
		registerOptions();
		for (OptionData<?> option : options) {
			option.validate();
		}
	}

	public <T> OptionBuilder<T> option(String name) {
		return addOption(new OptionData<>(name));
	}

	public <T> OptionBuilder<T> option(String name, Class<T> optionType) {
		return addOption(new OptionData<>(name));
	}

	public OptionBuilder<Boolean> boolOption(String name) {
		return addOption(
				new OptionData<Boolean>(name)
						.type(OptionType.BOOLEAN)
						.values(Arrays.asList(Boolean.TRUE, Boolean.FALSE))
						.formatter(b -> b ? "yes" : "no")
						.parser(val -> parseBoolOption(name, val)));
	}

	public OptionBuilder<String> strOption(String name) {
		return addOption(
				new OptionData<String>(name)
						.type(OptionType.STRING)
						.formatter(v -> v)
						.parser(v -> v));
	}

	public OptionBuilder<Integer> intOption(String name) {
		return addOption(
				new OptionData<Integer>(name)
						.type(OptionType.NUMBER)
						.formatter(Object::toString)
						.parser(Integer::parseInt));
	}

	public <E extends Enum<?>> OptionBuilder<E> enumOption(String name, E[] values, Function<String, E> valueOf) {
		return addOption(
				new OptionData<E>(name)
						.type(OptionType.STRING)
						.values(Arrays.asList(values))
						.formatter(v -> v.name().toLowerCase(Locale.ROOT))
						.parser(v -> valueOf.apply(v.toUpperCase(Locale.ROOT))));
	}

	@Override
	public void setOptions(Map<String, String> map) {
		for (OptionData<?> option : options) {
			parseOption(option, map.get(option.name));
		}
	}

	@Override
	public List<OptionDescription> getOptionsDescriptions() {
		return Collections.unmodifiableList(options);
	}

	private static <T> void parseOption(OptionData<T> option, @Nullable String value) {
		T parsedValue;
		if (value == null) {
			parsedValue = option.defaultValue;
		} else {
			try {
				parsedValue = option.getParser().apply(value);
			} catch (Exception e) {
				throw new RuntimeException("Parse failed for option: " + option.name + ", value: " + value, e);
			}
		}
		try {
			option.getSetter().accept(parsedValue);
		} catch (Exception e) {
			throw new RuntimeException("Setter invoke failed for option: " + option.name + ", value: " + parsedValue, e);
		}
	}

	private static boolean parseBoolOption(String name, String val) {
		String valLower = val.trim().toLowerCase(Locale.ROOT);
		if (valLower.equals("yes") || valLower.equals("true")) {
			return true;
		}
		if (valLower.equals("no") || valLower.equals("false")) {
			return false;
		}
		throw new IllegalArgumentException("Unknown value '" + val + "' for option '" + name + "', expect: 'yes' or 'no'");
	}

	private <T> OptionBuilder<T> addOption(OptionBuilder<T> optionData) {
		this.options.add((OptionData<?>) optionData);
		return optionData;
	}

	protected static class OptionData<T> implements OptionDescription, OptionBuilder<T> {
		private final String name;
		private String desc;
		private List<T> values = List.of();
		private OptionType type = OptionType.STRING;
		private Set<OptionFlag> flags = EnumSet.noneOf(OptionFlag.class);
		private Function<String, T> parser;
		private Function<T, String> formatter;
		private Consumer<T> setter;
		private T defaultValue;

		public OptionData(String name) {
			this.name = name;
		}

		@Override
		public String name() {
			return name;
		}

		@Override
		public String description() {
			return desc;
		}

		@Override
		public List<String> values() {
			return values.stream().map(formatter).collect(Collectors.toList());
		}

		@Override
		public @Nullable String defaultValue() {
			return formatter.apply(defaultValue);
		}

		@Override
		public OptionType getType() {
			return type;
		}

		@Override
		public Set<OptionFlag> getFlags() {
			return flags;
		}

		@Override
		public OptionBuilder<T> description(String desc) {
			this.desc = desc;
			return this;
		}

		@Override
		public OptionBuilder<T> defaultValue(@Nullable T defValue) {
			this.defaultValue = defValue;
			return this;
		}

		@Override
		public OptionBuilder<T> parser(Function<String, T> parser) {
			this.parser = parser;
			return this;
		}

		@Override
		public OptionBuilder<T> formatter(Function<T, String> formatter) {
			this.formatter = formatter;
			return this;
		}

		@Override
		public OptionBuilder<T> setter(Consumer<T> setter) {
			this.setter = setter;
			return this;
		}

		@Override
		public OptionBuilder<T> type(OptionType optionType) {
			this.type = optionType;
			return this;
		}

		@Override
		public OptionBuilder<T> flags(OptionFlag... flags) {
			this.flags = EnumSet.copyOf(Arrays.asList(flags));
			return this;
		}

		@Override
		public OptionBuilder<T> values(List<T> values) {
			this.values = values;
			return this;
		}

		public Function<String, T> getParser() {
			return parser;
		}

		public Function<T, String> getFormatter() {
			return formatter;
		}

		public Consumer<T> getSetter() {
			return setter;
		}

		public void validate() {
			if (desc == null || desc.isEmpty()) {
				throw new IllegalArgumentException("Description should be set for option: " + name);
			}
			if (parser == null) {
				throw new IllegalArgumentException("Parser should be set for option: " + name);
			}
			if (formatter == null) {
				throw new IllegalArgumentException("Formatter should be set for option: " + name);
			}
			if (setter == null) {
				throw new IllegalArgumentException("Setter should be set for option: " + name);
			}
		}
	}
}

package jadx.gui.ui.graphs;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FlowLayout;
import java.util.Formatter;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.JCheckBox;
import javax.swing.JMenuBar;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.UIManager;

import jadx.api.JavaMethod;
import jadx.api.JavaNode;
import jadx.core.dex.nodes.ClassNode;
import jadx.core.dex.nodes.MethodNode;
import jadx.core.utils.DotGraphUtils;
import jadx.gui.treemodel.JClass;
import jadx.gui.ui.MainWindow;
import jadx.gui.utils.NLS;
import jadx.gui.utils.layout.WrapLayout;

import static jadx.core.utils.DotGraphUtils.formatColor;
import static jadx.core.utils.DotGraphUtils.toDotNodeName;

public class ClassMethodGraphDialog extends GraphDialog {
	private static final long serialVersionUID = -850803763322590708L;

	private static final String FONT = "fontname=\"Courier\" fontsize=12";
	private static final int CALLER_DEPTH_LIMIT = 10;

	private final ClassNode cls;
	private int nextNodeID = 0;
	private Map<JavaMethod, Integer> methodToNodeID;
	private Set<Edge> edges;
	private List<JavaMethod> javaMethods = List.of();
	private boolean longNames = false;

	public ClassMethodGraphDialog(MainWindow mainWindow, ClassNode cls) {
		super(mainWindow, String.format("%s: %s", NLS.str("graph_viewer.method_graph.title"), DotGraphUtils.classFormatName(cls, false)));
		this.cls = cls;
	}

	@Override
	public JMenuBar addMenuBar() {
		JMenuBar menuBar = super.addMenuBar();

		// Long names checkbox
		JCheckBox showLongNames = new JCheckBox(NLS.str("graph_viewer.long_names"));
		showLongNames.setSelected(false);
		showLongNames.addItemListener(e -> {
			longNames = showLongNames.isSelected();
			reload();
		});

		// Assemble menubar panel
		JPanel menuBarPanel = new JPanel();
		menuBarPanel.setOpaque(false);
		menuBarPanel.setLayout(new WrapLayout(FlowLayout.LEFT));
		menuBarPanel.add(showLongNames, BorderLayout.PAGE_START);

		// Add menubar panel to menuBar
		menuBar.add(menuBarPanel);
		return menuBar;
	}

	public static void open(MainWindow window, JClass node) {
		ClassNode cls = node.getCls().getClassNode();
		ClassMethodGraphDialog graphDialog = new ClassMethodGraphDialog(window, cls);
		graphDialog.addMenuBar();
		graphDialog.setVisible(true);
		graphDialog.reload();
	}

	public void reload() {
		SwingUtilities.invokeLater(() -> getPanel().setGraph(generateGraph(cls)));
	}

	private String generateGraph(ClassNode classNode) {
		Color themeBackground = UIManager.getColor("Panel.background");
		Color themeForeground = UIManager.getColor("Label.foreground");
		Color themeShade = UIManager.getColor("TextArea.background");

		String bgColor = "bgcolor=" + formatColor(themeBackground);
		String lineColor = "color=" + formatColor(themeForeground);
		String fontColor = "fontcolor=" + formatColor(themeForeground);
		String shadeColor = "fillcolor=" + formatColor(themeShade);

		try (Formatter f = new Formatter(new StringBuilder())) {
			// graph header
			f.format("digraph G {\n");
			f.format("%s\n", bgColor);
			f.format("node[shape=\"record\" style=\"filled\" %s %s %s %s]\n", FONT, fontColor, lineColor, shadeColor);
			f.format("edge[arrowtail=\"onormal\" arrowhead=\"onormal\" %s %s %s]\n", FONT, fontColor, lineColor);

			nextNodeID = 0;
			methodToNodeID = new HashMap<>();
			edges = new HashSet<>();

			List<MethodNode> methods = classNode.getMethods();
			javaMethods = methods.stream().map(MethodNode::getJavaNode).collect(Collectors.toList());
			for (JavaMethod javaMethod : javaMethods) {
				addNode(f, javaMethod);
				// add caller relationships
				addCallers(0, f, javaMethod);
			}
			// close graph
			f.format("}");
			return f.toString();
		}
	}

	private void addCallers(int depth, Formatter f, JavaMethod javaMethod) {
		if (depth >= CALLER_DEPTH_LIMIT) {
			return;
		}
		List<JavaNode> uses = javaMethod.getUseIn();
		// add "calls" relationships
		for (JavaNode node : uses) {
			if (!(node instanceof JavaMethod)) {
				continue;
			}
			JavaMethod caller = (JavaMethod) node;
			// Do not process callers that are not methods from the class
			if (!javaMethods.contains(node)) {
				continue;
			}
			int nodeID = addNode(f, caller);
			addEdge(f, nodeID, methodToNodeID.get(javaMethod));
			addCallers(depth + 1, f, caller);
		}
	}

	// Add a node representing method to the graph in f. Returns the ID of the new node
	private int addNode(Formatter f, JavaMethod method) {
		int nodeID;
		if (methodToNodeID.containsKey(method)) {
			nodeID = methodToNodeID.get(method);
		} else {
			nodeID = nextNodeID;
			nextNodeID++;
			methodToNodeID.put(method, nodeID);
		}
		String name = DotGraphUtils.methodFormatName(method, longNames);
		f.format("Node_%d [ label=\"{%s}\"]\n", nodeID, toDotNodeName(name));
		if (method.callsSelf()) {
			addEdge(f, nodeID, nodeID);
		}
		return nodeID;
	}

	// Add an edge between sourceID and destID to the graph in f
	private void addEdge(Formatter f, int sourceID, int destID) {
		Edge edge = new Edge(sourceID, destID);
		if (!edges.contains(edge)) {
			f.format("Node_%d -> Node_%d\n", sourceID, destID);
			edges.add(edge);
		}
	}
}

package jadx.core.dex.visitors.typeinference;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import org.jetbrains.annotations.Nullable;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import jadx.core.Consts;
import jadx.core.dex.instructions.InsnType;
import jadx.core.dex.instructions.args.ArgType;
import jadx.core.dex.instructions.args.InsnArg;
import jadx.core.dex.instructions.args.PrimitiveType;
import jadx.core.dex.instructions.args.RegisterArg;
import jadx.core.dex.instructions.args.SSAVar;
import jadx.core.dex.nodes.InsnNode;
import jadx.core.dex.nodes.MethodNode;
import jadx.core.utils.ListUtils;

/**
 * Slow and memory consuming multi-variable type search algorithm.
 * Used only if fast type propagation is failed for some variables.
 * <p>
 * Stages description:
 * - find all possible candidate types within bounds
 * - build dynamic constraint list for every variable
 * - run search by checking all candidates
 */
public class TypeSearch {
	private static final Logger LOG = LoggerFactory.getLogger(TypeSearch.class);

	private static final int VARS_PROCESS_LIMIT = 5_000;
	private static final int CANDIDATES_COUNT_LIMIT = 10;
	private static final int SEARCH_ITERATION_LIMIT = 1_000_000;

	private final MethodNode mth;
	private final TypeSearchState state;
	private final TypeCompare typeCompare;
	private final TypeUpdate typeUpdate;

	public TypeSearch(MethodNode mth) {
		this.mth = mth;
		this.state = new TypeSearchState(mth);
		this.typeUpdate = mth.root().getTypeUpdate();
		this.typeCompare = typeUpdate.getTypeCompare();
	}

	public boolean run() {
		if (mth.getSVars().size() > VARS_PROCESS_LIMIT) {
			mth.addWarnComment("Multi-variable search skipped. Vars limit reached: " + mth.getSVars().size()
					+ " (expected less than " + VARS_PROCESS_LIMIT + ")");
			return false;
		}
		mth.getSVars().forEach(this::fillTypeCandidates);
		mth.getSVars().forEach(this::collectConstraints);

		// quick search for variables without dependencies
		state.getUnresolvedVars().forEach(this::resolveIndependentVariables);

		boolean searchSuccess;
		List<TypeSearchVarInfo> vars = state.getUnresolvedVars();
		if (vars.isEmpty()) {
			searchSuccess = true;
		} else {
			searchSuccess = search(vars) && fullCheck(vars);
			if (Consts.DEBUG_TYPE_INFERENCE && !searchSuccess) {
				LOG.debug("Multi-variable search failed");
			}
		}
		if (searchSuccess) {
			return applyResolvedVars();
		}
		return false;
	}

	private boolean applyResolvedVars() {
		List<TypeSearchVarInfo> resolvedVars = state.getResolvedVars();
		List<TypeSearchVarInfo> updatedVars = new ArrayList<>();
		for (TypeSearchVarInfo var : resolvedVars) {
			SSAVar ssaVar = var.getVar();
			ArgType resolvedType = var.getCurrentType();
			if (!resolvedType.isTypeKnown()) {
				// ignore unknown variables
				continue;
			}
			if (resolvedType.equals(ssaVar.getTypeInfo().getType())) {
				// type already set
				continue;
			}
			ssaVar.setType(resolvedType);
			updatedVars.add(var);
		}
		boolean applySuccess = true;
		for (TypeSearchVarInfo var : updatedVars) {
			TypeUpdateResult res = typeUpdate.applyWithWiderIgnSame(mth, var.getVar(), var.getCurrentType());
			if (res == TypeUpdateResult.REJECT) {
				mth.addDebugComment("Multi-variable search result rejected for " + var);
				applySuccess = false;
			}
		}
		return applySuccess;
	}

	private boolean search(List<TypeSearchVarInfo> vars) {
		int len = vars.size();
		if (Consts.DEBUG_TYPE_INFERENCE) {
			LOG.debug("Run multi-variable search for {} vars: ", len);
			StringBuilder sb = new StringBuilder();
			long count = 1;
			for (TypeSearchVarInfo var : vars) {
				LOG.debug("  {}", var);
				int size = var.getCandidateTypes().size();
				sb.append(" * ").append(size);
				count *= size;
			}
			sb.append(" = ").append(count);
			LOG.debug(" max iterations count = {}", sb);
		}

		// prepare vars
		for (TypeSearchVarInfo var : vars) {
			var.reset();
		}
		// check all types combinations
		int n = 0;
		int i = 0;
		while (!fullCheck(vars)) {
			TypeSearchVarInfo first = vars.get(i);
			if (first.nextType()) {
				int k = i + 1;
				if (k >= len) {
					return false;
				}
				TypeSearchVarInfo next = vars.get(k);
				while (true) {
					if (next.nextType()) {
						k++;
						if (k >= len) {
							return false;
						}
						next = vars.get(k);
					} else {
						break;
					}
				}
			}
			n++;
			if (n > SEARCH_ITERATION_LIMIT) {
				if (Consts.DEBUG_TYPE_INFERENCE) {
					LOG.debug(" > iterations limit reached: {}", SEARCH_ITERATION_LIMIT);
				}
				return false;
			}
		}
		if (Consts.DEBUG_TYPE_INFERENCE) {
			LOG.debug(" > done after {} iterations", n);
		}
		// mark all vars as resolved
		for (TypeSearchVarInfo var : vars) {
			var.setTypeResolved(true);
		}
		return true;
	}

	private boolean resolveIndependentVariables(TypeSearchVarInfo varInfo) {
		boolean allRelatedVarsResolved = varInfo.getConstraints().stream()
				.flatMap(c -> c.getRelatedVars().stream())
				.allMatch(v -> state.getVarInfo(v).isTypeResolved());
		if (!allRelatedVarsResolved) {
			return false;
		}
		// variable is independent, run single search
		varInfo.reset();
		do {
			if (singleCheck(varInfo)) {
				varInfo.setTypeResolved(true);
				return true;
			}
		} while (!varInfo.nextType());

		return false;
	}

	private boolean fullCheck(List<TypeSearchVarInfo> vars) {
		for (TypeSearchVarInfo var : vars) {
			if (!singleCheck(var)) {
				return false;
			}
		}
		return true;
	}

	private boolean singleCheck(TypeSearchVarInfo var) {
		if (var.isTypeResolved()) {
			return true;
		}
		for (ITypeConstraint constraint : var.getConstraints()) {
			if (!constraint.check(state)) {
				return false;
			}
		}
		return true;
	}

	private void fillTypeCandidates(SSAVar ssaVar) {
		TypeSearchVarInfo varInfo = state.getVarInfo(ssaVar);
		ArgType immutableType = ssaVar.getImmutableType();
		if (immutableType != null) {
			varInfo.markResolved(immutableType);
			return;
		}
		ArgType currentType = ssaVar.getTypeInfo().getType();
		if (currentType.isTypeKnown()) {
			varInfo.markResolved(currentType);
			return;
		}

		Set<ArgType> assigns = new LinkedHashSet<>();
		Set<ArgType> uses = new LinkedHashSet<>();
		Set<ITypeBound> bounds = ssaVar.getTypeInfo().getBounds();
		for (ITypeBound bound : bounds) {
			if (bound.getBound() == BoundEnum.ASSIGN) {
				assigns.add(bound.getType());
			} else {
				uses.add(bound.getType());
			}
		}

		Set<ArgType> candidateTypes = new LinkedHashSet<>();
		addCandidateTypes(bounds, candidateTypes, assigns);
		addCandidateTypes(bounds, candidateTypes, uses);

		for (ArgType assignType : assigns) {
			addCandidateTypes(bounds, candidateTypes, getWiderTypes(assignType));
		}
		for (ArgType useType : uses) {
			addCandidateTypes(bounds, candidateTypes, getNarrowTypes(useType));
		}

		addUsageTypeCandidates(ssaVar, bounds, candidateTypes);

		int size = candidateTypes.size();
		if (size == 0) {
			varInfo.setTypeResolved(true);
			varInfo.setCurrentType(ArgType.UNKNOWN);
			varInfo.setCandidateTypes(List.of());
		} else if (size == 1) {
			varInfo.setTypeResolved(true);
			varInfo.setCurrentType(candidateTypes.iterator().next());
			varInfo.setCandidateTypes(List.of());
		} else {
			varInfo.setTypeResolved(false);
			varInfo.setCurrentType(ArgType.UNKNOWN);
			List<ArgType> types = new ArrayList<>(candidateTypes);
			types.sort(typeCompare.getReversedComparator());
			varInfo.setCandidateTypes(Collections.unmodifiableList(types));
		}
	}

	private void addUsageTypeCandidates(SSAVar ssaVar, Set<ITypeBound> bounds, Set<ArgType> candidateTypes) {
		for (RegisterArg useArg : ssaVar.getUseList()) {
			InsnNode parentInsn = useArg.getParentInsn();
			if (parentInsn != null) {
				InsnType insnType = parentInsn.getType();
				if (insnType == InsnType.APUT) {
					ArgType aputType = parentInsn.getArg(2).getType();
					if (aputType.isTypeKnown()) {
						addCandidateType(bounds, candidateTypes, ArgType.array(aputType));
					}
				}
			}
		}
	}

	private void addCandidateTypes(Set<ITypeBound> bounds, Set<ArgType> collectedTypes, Collection<ArgType> candidateTypes) {
		for (ArgType candidateType : candidateTypes) {
			if (addCandidateType(bounds, collectedTypes, candidateType)) {
				return;
			}
		}
	}

	private boolean addCandidateType(Set<ITypeBound> bounds, Set<ArgType> collectedTypes, ArgType candidateType) {
		if (candidateType.isTypeKnown() && typeUpdate.inBounds(bounds, candidateType)) {
			collectedTypes.add(candidateType);
			if (collectedTypes.size() > CANDIDATES_COUNT_LIMIT) {
				return true;
			}
		}
		return false;
	}

	private List<ArgType> getWiderTypes(ArgType type) {
		if (type.isTypeKnown()) {
			if (type.isObject()) {
				Set<String> ancestors = mth.root().getClsp().getSuperTypes(type.getObject());
				return ancestors.stream().map(ArgType::object).collect(Collectors.toList());
			}
		} else {
			return expandUnknownType(type);
		}
		return List.of();
	}

	private List<ArgType> getNarrowTypes(ArgType type) {
		if (type.isTypeKnown()) {
			if (type.isObject()) {
				if (type.equals(ArgType.OBJECT)) {
					// a lot of objects to return
					return List.of(ArgType.OBJECT);
				}
				List<String> impList = mth.root().getClsp().getImplementations(type.getObject());
				return impList.stream().map(ArgType::object).collect(Collectors.toList());
			}
		} else {
			return expandUnknownType(type);
		}
		return List.of();
	}

	private List<ArgType> expandUnknownType(ArgType type) {
		List<ArgType> list = new ArrayList<>();
		for (PrimitiveType possibleType : type.getPossibleTypes()) {
			list.add(ArgType.convertFromPrimitiveType(possibleType));
		}
		return list;
	}

	private void collectConstraints(SSAVar var) {
		TypeSearchVarInfo varInfo = state.getVarInfo(var);
		if (varInfo.isTypeResolved()) {
			varInfo.setConstraints(List.of());
			return;
		}
		varInfo.setConstraints(new ArrayList<>());
		addConstraint(varInfo, makeConstraint(var.getAssign()));
		for (RegisterArg regArg : var.getUseList()) {
			addConstraint(varInfo, makeConstraint(regArg));
		}
	}

	private void addConstraint(TypeSearchVarInfo varInfo, ITypeConstraint constraint) {
		if (constraint != null) {
			varInfo.getConstraints().add(constraint);
		}
	}

	@Nullable
	private ITypeConstraint makeConstraint(RegisterArg arg) {
		InsnNode insn = arg.getParentInsn();
		if (insn == null || arg.isTypeImmutable()) {
			return null;
		}
		switch (insn.getType()) {
			case MOVE:
				return makeMoveConstraint(insn, arg);

			case PHI:
				return makePhiConstraint(insn, arg);

			default:
				return null;
		}
	}

	@Nullable
	private ITypeConstraint makeMoveConstraint(InsnNode insn, RegisterArg arg) {
		if (!insn.getArg(0).isRegister()) {
			return null;
		}
		return new AbstractTypeConstraint(insn, arg) {
			@Override
			public boolean check(TypeSearchState state) {
				ArgType resType = state.getArgType(insn.getResult());
				ArgType argType = state.getArgType(insn.getArg(0));
				TypeCompareEnum res = typeCompare.compareTypes(resType, argType);
				return res.isEqual() || res.isWider();
			}
		};
	}

	private ITypeConstraint makePhiConstraint(InsnNode insn, RegisterArg arg) {
		return new AbstractTypeConstraint(insn, arg) {
			@Override
			public boolean check(TypeSearchState state) {
				ArgType resType = state.getArgType(insn.getResult());
				for (InsnArg insnArg : insn.getArguments()) {
					ArgType argType = state.getArgType(insnArg);
					if (!argType.equals(resType)) {
						return false;
					}
				}
				return true;
			}
		};
	}
}

