public static <T> List<T> filter(Collection<T> list, Predicate<T> filter) {
	if (list == null || list.isEmpty()) {
		return List.of();
	}
	List<T> result = new ArrayList<>();
	for (T element : list) {
		if (filter.test(element)) {
			result.add(element);
		}
	}
	return result;
}

