# Pattern: if (expr) { return true; } return false; (or with else { return false; })
# or: if (expr) { return false; } return true;
result = subprocess.run(['grep', '-rn', '-A3', r'if (', 'jadx-core/src/main/java/', 'jadx-gui/src/main/java/'], capture_output=True, text=True)
lines = result.stdout.split('\n')

hits = []
i = 0
while i < len(lines) - 3:
    line = lines[i]
    if 'return true;' in lines[i+1] and 'return false;' in lines[i+2]:
        hits.append((line, lines[i+1], lines[i+2]))
    if 'return false;' in lines[i+1] and 'return true;' in lines[i+2]:
        hits.append((line, lines[i+1], lines[i+2]))
    i += 1

for h in hits[:15]:
    print('---')
    for l in h:
        print(l)
" 2>/dev/null | head -60

